def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([0]), fmt([1, 1]), fmt([0, 0, 0]), fmt([1, 0, 1, 1, 0, 1, 1, 1]),
             fmt([1] * 7), fmt([0, 1, 1, 1]), fmt([1, 1, 1, 0])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for p in (0.3, 0.6, 0.9):
            tests.append(fmt([1 if rng.random() < p else 0 for _ in range(n)]))
    N = 100000
    tests.append(fmt([1] * N))
    tests.append(fmt([0] * N))
    tests.append(fmt([1 if rng.random() < 0.999 else 0 for _ in range(N)]))
    tests.append(fmt([i % 2 for i in range(N)]))
    return tests

